fn check_match_at(main: &Vec<i32>, sub: &Vec<i32>, start: usize) -> bool {
    // Precondition (as described): start + sub.len() <= main.len()
    if start > main.len() || sub.len() > main.len() - start {
        return false;
    }
    for j in 0..sub.len() {
        if main[start + j] != sub[j] {
            return false;
        }
    }
    true
}

fn is_sub_array(main: &Vec<i32>, sub: &Vec<i32>) -> bool {
    if sub.is_empty() {
        return true;
    }
    if sub.len() > main.len() {
        return false;
    }

    let last_start = main.len() - sub.len();
    for k in 0..=last_start {
        if check_match_at(main, sub, k) {
            return true;
        }
    }
    false
}